/bin/bash -lc "cat <<'EOF' > app.js
const COURSES = [
 {id:'ART-110',title:'Drawing Outside the Lines',category:'Arts',level:'Beginner',credits:3,instructor:'Maya Chen',schedule:'Mon · Wed, 10:00 AM',color:'lilac',icon:'✳',description:'Build a daily sketch practice and learn to see the world differently.'},
 {id:'BIO-204',title:'The Secret Life of Cells',category:'Science',level:'Intermediate',credits:4,instructor:'Dr. Lena Ortiz',schedule:'Tue · Thu, 9:30 AM',color:'mint',icon:'◉',description:'A hands-on journey into the tiny systems that make life possible.'},
 {id:'CS-150',title:'Code Your First Game',category:'Technology',level:'Beginner',credits:3,instructor:'Ravi Patel',schedule:'Mon · Wed, 1:00 PM',color:'peach',icon:'⌘',description:'Learn programming fundamentals by making a game worth playing.'},
 {id:'BUS-218',title:'Ideas Into Action',category:'Business',level:'Intermediate',credits:3,instructor:'Nina Brooks',schedule:'Tue · Thu, 11:00 AM',color:'yellow',icon:'↗',description:'Turn a good idea into a thoughtful, practical business plan.'},
 {id:'HUM-132',title:'Stories That Shape Us',category:'Humanities',level:'Beginner',credits:3,instructor:'Prof. Elias Reed',schedule:'Mon · Wed, 2:30 PM',color:'blue',icon:'❝',description:'Explore the stories and myths that continue to shape culture.'},
 {id:'SCI-240',title:'Climate, City, Future',category:'Science',level:'Advanced',credits:4,instructor:'Dr. Amara Singh',schedule:'Wed · Fri, 9:00 AM',color:'mint',icon:'♧',description:'Use real city data to imagine more resilient urban futures.'},
 {id:'ART-225',title:'Design for Good',category:'Arts',level:'Intermediate',credits:3,instructor:'Jordan Kim',schedule:'Tue · Thu, 1:30 PM',color:'lilac',icon:'✿',description:'Use design research and visual thinking to solve human problems.'},
 {id:'CS-220',title:'The Internet, Explained',category:'Technology',level:'Intermediate',credits:4,instructor:'Alex Morgan',schedule:'Mon · Wed, 11:00 AM',color:'peach',icon:'◎',description:'Understand the systems that connect the world, one layer at a time.'},
 {id:'BUS-105',title:'Money Moves',category:'Business',level:'Beginner',credits:3,instructor:'Tara Williams',schedule:'Tue · Thu, 3:00 PM',color:'yellow',icon:'"'$'"',description:'A friendly, practical introduction to personal finance.'},
 {id:'HUM-245',title:'Philosophy for Real Life',category:'Humanities',level:'Advanced',credits:3,instructor:'Prof. Sam Okafor',schedule:'Mon · Wed, 9:30 AM',color:'blue',icon:'◇',description:'Bring timeless questions into conversation with modern life.'},
 {id:'BIO-118',title:'Plants Are People Too',category:'Science',level:'Beginner',credits:4,instructor:'Dr. Mei Tan',schedule:'Tue · Thu, 10:00 AM',color:'mint',icon:'♧',description:'Meet the clever, responsive organisms growing all around us.'},
 {id:'ART-305',title:'Photography in the Wild',category:'Arts',level:'Advanced',credits:3,instructor:'Cam Rivera',schedule:'Fri, 12:00 PM',color:'lilac',icon:'◉',description:'Practice documentary photography through fieldwork and critique.'},
 {id:'CS-310',title:'Creative AI Lab',category:'Technology',level:'Advanced',credits:4,instructor:'Sasha Ivanov',schedule:'Tue · Thu, 2:00 PM',color:'peach',icon:'✧',description:'Prototype playful, useful projects with emerging AI tools.'},
 {id:'BUS-230',title:'The Art of Negotiation',category:'Business',level:'Intermediate',credits:3,instructor:'Renee Davis',schedule:'Mon · Wed, 3:30 PM',color:'yellow',icon:'↔',description:'Practice listening, collaboration, and finding common ground.'},
 {id:'HUM-110',title:'Language & Power',category:'Humanities',level:'Beginner',credits:3,instructor:'Prof. Noor Haddad',schedule:'Tue · Thu, 9:00 AM',color:'blue',icon:'Aa',description:'Notice how the words we choose can open doors and change minds.'},
 {id:'SCI-160',title:'Ocean Worlds',category:'Science',level:'Beginner',credits:4,instructor:'Dr. Theo Park',schedule:'Mon · Wed, 12:30 PM',color:'mint',icon:'≈',description:'Dive into ocean science, from coral reefs to the deep sea.'}
];
const STORE_KEY='campusRegistrationV1';
function getRegistration(){try{return JSON.parse(localStorage.getItem(STORE_KEY))||null}catch{return null}}
function saveRegistration(value){localStorage.setItem(STORE_KEY,JSON.stringify(value))}
function getSelected(){return getRegistration()?.courses||[]}
function initMenu(){const button=document.querySelector('.menu-toggle'),nav=document.querySelector('#primary-nav');if("'!button||!nav)return;button.addEventListener('"'click',()=>{const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String("'!open));nav.classList.toggle('"'nav-open',"'!open)})}
function renderCatalog(){const grid=document.querySelector('"'#course-grid');if("'!grid)return;const search=document.querySelector('"'#course-search'),category=document.querySelector('#category-filter'),level=document.querySelector('#level-filter'),credits=document.querySelector('#credits-filter'),count=document.querySelector('#course-count'),summary=document.querySelector('#results-summary'),empty=document.querySelector('#empty-state');const params=new URLSearchParams(location.search);if(params.has('category'))category.value=params.get('category');
function update(){const query=search.value.trim().toLowerCase();const filtered=COURSES.filter(c=>("'!query||`${c.id} ${c.title} ${c.category} ${c.instructor} ${c.description}`.toLowerCase().includes(query))&&(category.value==='"'all'||c.category===category.value)&&(level.value==='all'||c.level===level.value)&&(credits.value==='all'||String(c.credits)===credits.value));const selected=new Set(getSelected());grid.innerHTML=filtered.map(c=>"'`<article class="course-card"><div class="course-art art-${c.color}" aria-hidden="true"><span class="course-art-icon">${c.icon}</span><span class="course-art-code">${c.id}</span></div><div class="course-card-body"><div class="course-meta"><span class="category-pill">${c.category}</span><span>${c.level}</span></div><h2>${c.title}</h2><p>${c.description}</p><div class="course-details"><span>${c.credits} credits</span><span class="detail-dot" aria-hidden="true">·</span><span>${c.schedule}</span></div><a class="course-action" href="registration.html" aria-label="${selected.has(c.id)?'"'Update registration for':'Register for'} "'${c.title}">${selected.has(c.id)?'"'In your plan':'Explore course'} <span aria-hidden=\"true\">→</span></a></div></article>"'`).join('"'');count.textContent=filtered.length;summary.textContent=filtered.length===COURSES.length?'Showing all 16 courses':"'`Showing ${filtered.length} of 16 courses`;empty.hidden=filtered.length>0;grid.hidden=filtered.length===0}
[search,category,level,credits].forEach(el=>el.addEventListener(el===search?'"'input':'change',update));document.querySelector('#clear-filters').addEventListener('click',()=>{search.value='';category.value=level.value=credits.value='all';update();search.focus()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search.focus()}});update()}
function renderRegistration(){const list=document.querySelector('#registration-course-list');if("'!list)return;const reg=getRegistration();const form=document.querySelector('"'#registration-form');if(reg){form.elements.studentName.value=reg.name||'';form.elements.studentEmail.value=reg.email||'';form.elements.studentId.value=reg.studentId||'';form.elements.studentMajor.value=reg.major||''}const chosen=new Set(getSelected());list.innerHTML=COURSES.map(c=>"'`<label class="registration-course"><input type="checkbox" name="courses" value="${c.id}" ${chosen.has(c.id)?'"'checked':''}><span class=\"check-mark\" aria-hidden=\"true\"></span><span class=\"registration-course-info\"><strong>"'${c.title}</strong><small>${c.id} · ${c.category} · ${c.schedule}</small></span><span class="registration-course-credits">${c.credits} cr</span></label>`).join('"'');const update=()=>{const ids=[...list.querySelectorAll('input:checked')].map(i=>i.value);const courses=COURSES.filter(c=>ids.includes(c.id));const total=courses.reduce((n,c)=>n+c.credits,0);document.querySelector('#selected-courses').innerHTML=courses.length?courses.map(c=>"'`<div class="selected-course"><span>${c.title}</span><small>${c.credits} credits</small></div>`).join('"''):'<p class=\"summary-empty\">No courses selected yet.</p>';const totalEl=document.querySelector('#total-credits');totalEl.innerHTML="'`${total} <small>/ 18</small>`;totalEl.classList.toggle('"'over-limit',total>18);list.querySelectorAll('input').forEach(i=>{i.disabled="'!i.checked&&total>=18})};list.addEventListener('"'change',update);update();const modal=document.querySelector('#confirmation-modal');const close=()=>{modal.hidden=true;document.querySelector('#confirmation-done').focus()};document.querySelector('.modal-close').addEventListener('click',close);document.querySelector('#confirmation-done').addEventListener('click',()=>location.href='profile.html');modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&"'!modal.hidden)close()});form.addEventListener('"'submit',e=>{e.preventDefault();const data=new FormData(form),name=String(data.get('studentName')||'').trim(),email=String(data.get('studentEmail')||'').trim(),studentId=String(data.get('studentId')||'').trim(),major=String(data.get('studentMajor')||'');let valid=true;[['student-name',"'!name,'"'Please enter your full name.'],['student-email',"'!email||!/''^'"\\S+@\\S+\\.\\S+"'$/.test(email),'"'Enter a valid email address.'],['student-id',"'!studentId,'"'Please enter your student ID.']].forEach(([id,bad,message])=>{const input=document.getElementById(id),error=document.getElementById(id+'-error');error.textContent=bad?message:'';input.setAttribute('aria-invalid',String(bad));if(bad)valid=false});const courses=COURSES.filter(c=>[...list.querySelectorAll('input:checked')].some(i=>i.value===c.id));if(courses.length===0){const first=list.querySelector('input');first.focus();first.setCustomValidity('Choose at least one course.');first.reportValidity();setTimeout(()=>first.setCustomValidity(''),1500);valid=false}if(courses.reduce((sum,c)=>sum+c.credits,0)>18)valid=false;if("'!valid){form.querySelector('"'[aria-invalid=\"true\"]')?.focus();return}const registration={name,email,studentId,major,courses:courses.map(c=>c.id),registeredAt:new Date().toISOString()};saveRegistration(registration);document.querySelector('#confirmation-details').textContent="'`${courses.length} ${courses.length===1?'"'course':'courses'} · "'${courses.reduce((sum,c)=>sum+c.credits,0)} credits`;modal.hidden=false;modal.querySelector('"'.modal-close').focus()})}
function renderProfile(){if("'!document.querySelector('"'#registered-table-body'))return;const reg=getRegistration(),body=document.querySelector('#registered-table-body'),empty=document.querySelector('#profile-empty');if("'!reg){empty.hidden=false;return}document.querySelector('"'#profile-name').textContent=reg.name;document.querySelector('#profile-email').textContent=[reg.email,reg.major].filter(Boolean).join(' · ')||'Your student profile';document.querySelector('#profile-avatar').textContent=reg.name.trim().split(/\\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase();const courses=COURSES.filter(c=>reg.courses.includes(c.id));document.querySelector('#profile-course-count').textContent=courses.length;document.querySelector('#profile-credits').textContent=courses.reduce((s,c)=>s+c.credits,0);empty.hidden=courses.length>0;body.innerHTML=courses.map(c=>"'`<tr><th scope="row"><span class="table-course-id">${c.id}</span><strong>${c.title}</strong></th><td><span class="category-pill">${c.category}</span></td><td>${c.instructor}</td><td>${c.schedule}</td><td>${c.credits}</td></tr>`).join('"'')}
document.addEventListener('DOMContentLoaded',()=>{initMenu();renderCatalog();renderRegistration();renderProfile()});
EOF"

